bool NativeRetainedOpaquePhaseCanonicalPixelCertified(std::string_view source, std::span<const uint8_t> bytes) noexcept {
    try {
        for(const auto& pin:kPixels)if(pin.source==source)
            return bytes.size()==pin.canonical_bytes && ContentHash(bytes)==pin.canonical;
    } catch(...) {}
    return false;
}
bool NativeRetainedOpaquePhaseModuleCertified(std::string_view source, bool pixel, NativeShaderVariant variant, std::span<const uint8_t> bytes) noexcept {
    try {
        if(pixel) {
            if(variant==NativeShaderVariant::RetainedOpaquePhaseConservativeV4) {
                for(const auto& pin:kConservativePixels)if(pin.source==source)
                    return bytes.size()==pin.bytes && ContentHash(bytes)==pin.spirv;
                return false;
            }
            if(variant!=NativeShaderVariant::RetainedOpaquePhaseV3)return false;
            for(const auto& pin:kPixels)if(pin.source==source)
                return bytes.size()==pin.packed_bytes && ContentHash(bytes)==pin.packed;
        } else {
            if(variant!=NativeShaderVariant::Unmodified)return false;
            for(const auto& pin:kVertices)if(pin.source==source)
                return bytes.size()==pin.bytes && ContentHash(bytes)==pin.spirv;
        }
    } catch(...) {}
    return false;
}
